referenceSolutions.javascript:
export function solve(values, value, start, end) {
  const result = values.slice();
  const norm = (i) => Math.max(0, Math.min(values.length, i < 0 ? values.length + i : i));
  for (let i = norm(start); i < norm(end); i++) result[i] = value;
  return result;
}

