export function solve(values: any[], value: any, start: number, end: number): any {
  const result = values.slice();
  const norm = (i: number): number =>
    Math.max(0, Math.min(values.length, i < 0 ? values.length + i : i));
  for (let i = norm(start); i < norm(end); i++) result[i] = value;
  return result;
}
